create table if not exists public.network_profiles (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,enterprise_id uuid references public.enterprises(id) on delete set null,owner_type text not null default 'person' check(owner_type in ('person','enterprise')),category text not null,display_name text not null,region text,website_url text,public_description text,public_visible boolean not null default true,status public.review_status not null default 'submitted',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,category));
