create table if not exists public.reward_catalog (id uuid primary key default gen_random_uuid(),enterprise_id uuid references public.enterprises(id) on delete set null,category text not null check(category in ('daily','selected','rare','secret')),title text not null,description text,point_cost integer not null default 0 check(point_cost>=0),stock_total integer,stock_remaining integer,min_level integer check(min_level between 1 and 5),min_footprints integer not null default 0,status public.review_status not null default 'draft',starts_at timestamptz,ends_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
